import * as React from "react"
import { Link, graphql, type PageProps } from "gatsby"

import { Layout } from "../components/layout"
import { Seo } from "../components/seo"
import { Article } from "../components/article"
import { useTranslation } from '../utils/i18n'

function PostTemplate({
  data,
  pageContext,
  location,
}: PageProps<DataProps, { postCategory: string }>) {
  const { t } = useTranslation()
  return (
    <Layout location={location}>
      <Article post={data.post} />
      <p>
        {data.previous && (
          <>
            <Link to={data.previous.fields.slug} rel="prev">
            {(t(`${pageContext.postCategory}-prev`))}
            </Link>{" "}
          </>
        )}
        {data.next && (
          <>
            <Link to={data.next.fields.slug} rel="next">
            {(t(`${pageContext.postCategory}-next`))}
            </Link>{" "}
          </>
        )}
        <Link to={`/${pageContext.postCategory}/`}>{t(`${pageContext.postCategory}-list`)}</Link>{" "}
      </p>
    </Layout>
  )
}

export function Head({ data: { post } }: PageProps<DataProps>) {
  return (
    <Seo
      title={post.frontmatter.title || post.frontmatter.date}
      description={post.frontmatter.description || post.excerpt}
    />
  )
}

export default PostTemplate

type DataProps = {
  site: {
    siteMetadata: {
      siteUrl: string
      author: {
        name: string
      }
    }
  }
  post: {
    id: string
    excerpt: string
    html: string
    fields: { slug: string }
    frontmatter: {
      title?: string
      date: string
      description: string
    }
  }
  previous?: {
    fields: { slug: string }
    frontmatter: {
      date: string
    }
  }
  next?: {
    fields: { slug: string }
    frontmatter: {
      date: string
    }
  }
}

export const pageQuery = graphql`
  query BlogPostBySlug(
    $id: String!
    $previousPostId: String
    $nextPostId: String
  ) {
    site {
      siteMetadata {
        siteUrl
        title
        author {
          name
        }
      }
    }
    post: markdownRemark(id: { eq: $id }) {
      id
      excerpt(pruneLength: 160)
      html
      fields {
        slug
      }
      frontmatter {
        date(formatString: "MMMM DD, YYYY")
        title
        description
      }
    }
    previous: markdownRemark(id: { eq: $previousPostId }) {
      fields {
        slug
      }
      frontmatter {
        title
      }
    }
    next: markdownRemark(id: { eq: $nextPostId }) {
      fields {
        slug
      }
      frontmatter {
        title
      }
    }
  }
`
